import java.util.*;
import java.util.stream.*;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n_elements = scanner.nextInt();
        int[] vec = new int[n_elements];
        for (int i = 0; i < n_elements; i++) {
            vec[i] = scanner.nextInt();
        }
        Arrays.sort(vec);
        int limit_value = scanner.nextInt();
        int max_len = -1;
        for (int i = 0; i < n_elements; i++) {
            int target = vec[i] + limit_value;
            int upper_idx = upperBound(vec, target);
            max_len = Math.max(max_len, upper_idx - i);
        }
        System.out.println(max_len);
    }

    private static int upperBound(int[] arr, int target) {
        int low = 0, high = arr.length;
        while (low < high) {
            int mid = (low + high) / 2;
            if (arr[mid] > target) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }
}
